#!/usr/bin/env python3
from __future__ import annotations
import base64, hashlib, io, json
from pathlib import Path
import zipfile

V2_SHA256 = "1fe26cbb93e2ff46f97218c1f7f2d6da07447f9c3aef98f7bdede6a97ebdba65"
AI2_SHA256 = "7c52c8c34ceb922f407d955f1efa3374711204c2be92525ce39bab395f2a7913"
V2_ARCHIVE = ""
AI2_ARCHIVE = ""
ROOT = Path.cwd()

def fail(msg: str) -> None:
    raise SystemExit(f"ERROR: {msg}")

def decode_archive(b64: str, expected_sha: str, label: str) -> bytes:
    data = base64.b64decode(b64)
    got = hashlib.sha256(data).hexdigest()
    if got != expected_sha:
        fail(f"{label} SHA256 mismatch: expected {expected_sha}, got {got}")
    return data

def extract_v2(data: bytes) -> list[str]:
    written=[]
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for info in z.infolist():
            name=info.filename.replace("\\","/")
            if not name or name.endswith("/"):
                continue
            parts=Path(name).parts
            if parts and parts[0]=="gts_project":
                parts=parts[1:]
            if not parts:
                continue
            target=ROOT.joinpath(*parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.exists():
                fail(f"CONFLICT: {target} already exists. Nothing overwritten.")
            target.write_bytes(z.read(info))
            written.append(str(target.relative_to(ROOT)))
    return written

def extract_ai2(data: bytes) -> list[str]:
    written=[]
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for info in z.infolist():
            name=info.filename.replace("\\","/")
            if not name or name.endswith("/"):
                continue
            target=ROOT.joinpath(*Path(name).parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.exists():
                fail(f"CONFLICT: {target} already exists. Nothing overwritten.")
            target.write_bytes(z.read(info))
            written.append(str(target.relative_to(ROOT)))
    return written

def write_new(rel: str, text: str) -> None:
    p=ROOT/rel
    p.parent.mkdir(parents=True, exist_ok=True)
    if p.exists():
        fail(f"CONFLICT: {p} already exists. Nothing overwritten.")
    p.write_text(text, encoding="utf-8")

def main():
    v2=decode_archive(V2_ARCHIVE,V2_SHA256,"GTS_V2")
    ai2=decode_archive(AI2_ARCHIVE,AI2_SHA256,"GTS_02_instruments")
    v2_written=extract_v2(v2)
    ai2_written=extract_ai2(ai2)

    write_new("02_instruments/__init__.py", '''GTS 02_instruments compatibility package.
AI-2 source files remain unchanged; this initializer only makes their original
local absolute imports work when imported as the numbered GTS package.
''')

    # Install import aliases without changing AI-2 source files.
    init = ROOT/"02_instruments/__init__.py"
    init.write_text("""try:
    from . import instrument_types as _instrument_types
    import sys as _sys
    _sys.modules.setdefault("instrument_types", _instrument_types)
    from . import instrument_master as _instrument_master
    _sys.modules.setdefault("instrument_master", _instrument_master)
    from . import expiry_calendar as _expiry_calendar
    _sys.modules.setdefault("expiry_calendar", _expiry_calendar)
except ImportError:
    # Pytest can load numeric-folder __init__ as a top-level test module.
    pass
""", encoding="utf-8")

    write_new("06_options_engine/instrument_wiring.py", '''from __future__ import annotations
import importlib
from dataclasses import dataclass
from datetime import date

_types = importlib.import_module("02_instruments.instrument_types")
_master = importlib.import_module("02_instruments.instrument_master")
_builder = importlib.import_module("02_instruments.contract_builder")
_calendar = importlib.import_module("02_instruments.expiry_calendar")

InstrumentMaster = _master.InstrumentMaster
ContractBuilder = _builder.ContractBuilder
ContractBuildError = _builder.ContractBuildError

@dataclass(frozen=True)
class OptionContractContext:
    symbol: str
    exchange: str
    strike: float
    expiry: str
    option_type: str
    lot_size: int
    tick_size: float

def build_option_context(master: InstrumentMaster, symbol: str,
                         strike: float, expiry: str, option_type: str) -> OptionContractContext:
    c = ContractBuilder(master).build_option(symbol, strike, expiry, option_type)
    return OptionContractContext(c.underlying_symbol, c.exchange, c.strike,
                                 c.expiry, c.option_type, c.lot_size, c.tick_size)

def next_expiry_for_instrument(master: InstrumentMaster, symbol: str,
                               reference_date: date):
    instrument = master.get(symbol)
    return _calendar.next_expiry(reference_date, instrument.expiry_frequency)
''')

    write_new("29_docs/AI2_LIVE_WIRING_BLUEPRINT.md", '''# GTS AI-2 LIVE WIRING RECORD

This is an implementation record, not a pre-built future architecture.

- `02_instruments/`: AI-2 owns instrument, contract and expiry identity.
- `04_indicators/`: limited indicator implementation supplied in V2.
- `06_options_engine/`: supplied V2 Options + Expiry Specialist remains canonical.
- Option market data is data input; it is not duplicated inside `02_instruments`.

Flow:
`02_instruments` -> validated instrument/contract/expiry context
-> `06_options_engine` V2 specialist.

`04_indicators` remains separate and unchanged.

The V2 specialist is not regenerated, reduced, or replaced.
No second Expiry Specialist is created.
No AI-3/AI-4/Risk/Execution/Broker logic is generated at this stage.
''')

    write_new("28_tests/test_ai2_v2_wiring.py", '''import importlib
from datetime import date

def test_ai2_package_imports():
    assert importlib.import_module("02_instruments") is not None

def test_ai2_v2_option_context():
    m = importlib.import_module("02_instruments.instrument_master")
    w = importlib.import_module("06_options_engine.instrument_wiring")
    master = m.default_instrument_master()
    ctx = w.build_option_context(master, "NIFTY", 22000, "2026-09-25", "CE")
    assert ctx.symbol == "NIFTY"
    assert ctx.lot_size == 25
    assert ctx.option_type == "CE"

def test_expiry_identity_boundary():
    m = importlib.import_module("02_instruments.instrument_master")
    w = importlib.import_module("06_options_engine.instrument_wiring")
    master = m.default_instrument_master()
    expiry = w.next_expiry_for_instrument(master, "NIFTY", date(2026, 9, 15))
    assert expiry is not None and expiry >= date(2026, 9, 15)

def test_v2_options_package_imports():
    assert importlib.import_module("06_options_engine") is not None

def test_v2_indicator_package_imports():
    assert importlib.import_module("04_indicators") is not None
''')

    manifest={
      "system":"GTS","stage":"AI-2 integration preparation",
      "sources":{
        "GTS_V2.zip":{"sha256":V2_SHA256,"role":"canonical tested V2 Expiry Specialist / Options Intelligence"},
        "GTS_02_instruments.zip":{"sha256":AI2_SHA256,"role":"AI-2 Instruments"}
      },
      "placement":{
        "02_instruments":"Instrument/Contract/Expiry identity",
        "04_indicators":"Limited indicators supplied by V2",
        "06_options_engine":"V2 Options + Expiry Specialist"
      },
      "generated_only":[
        "02_instruments/__init__.py",
        "06_options_engine/instrument_wiring.py",
        "29_docs/AI2_LIVE_WIRING_BLUEPRINT.md",
        "28_tests/test_ai2_v2_wiring.py",
        "AI2_INTEGRATION_MANIFEST.json"
      ],
      "preserve_sources":True
    }
    write_new("AI2_INTEGRATION_MANIFEST.json",json.dumps(manifest,indent=2)+"\n")

    print("GTS AI-2 INTEGRATION PREPARATION COMPLETE")
    print("V2 source files placed:",len(v2_written))
    print("AI-2 source files placed:",len(ai2_written))
    print("V2 and AI-2 source logic preserved.")
    print("Only compatibility/wiring/tests/docs generated.")

if __name__=="__main__":
    main()
